    for (int i = 0; i < len; i++)
        mp[inorder[i]] = i;

    // Initialize postorder index as the last element
    int postIndex = len - 1;

    // Call the recursive utility function to build the tree
    return buildUtil(inorder, postorder, 0, len - 1, postIndex, mp);
